# change: alf_progress_tracker
# hooks: alf_before_step, alf_after_step
# max_note_chars: 800, state_bytes: 800
import re

_APPLIANCES = ("microwave", "sinkbasin", "fridge", "bathtub", "toiletbasin")

_PICK_RE = re.compile(r"You pick up the (.+?) from the (.+?)\.")
_PUT_RE = re.compile(r"You put the (.+?) in/on the (.+?)\.")
_ARRIVE_RE = re.compile(r"You arrive at (.+?)\.")


def _clip(text, limit=190):
    if len(text) <= limit:
        return text
    return text[: limit - 3] + "..."


def alf_before_step(view, state):
    facts = []
    discourage = []
    adm = view.get("admissible_commands") or []

    task = ""
    for line in (view.get("initial_observation") or "").split("\n"):
        line = line.strip()
        if line.lower().startswith("your task is to:"):
            task = line
            break

    if task:
        facts.append(_clip("Keep the goal in mind: " + task))

    if state:
        holding = state.get("holding") or []
        if holding:
            facts.append(_clip("Currently holding: " + ", ".join(holding)))
        else:
            facts.append("Hands are empty.")

        empties = state.get("empty_seen") or []
        if empties:
            facts.append(_clip(
                "Already searched and empty: " + ", ".join(empties)
                + ". Avoid re-searching these unless the task names them."))
            for r in empties:
                cmd = "go to " + r
                if (
                    cmd in adm
                    and r not in task
                    and not any(a in r.lower() for a in _APPLIANCES)
                ):
                    discourage.append(cmd)

        last_action = state.get("last_action") or ""
        repeats = state.get("repeat_count") or 0
        if last_action and last_action in adm:
            if state.get("last_nothing"):
                discourage.append(last_action)
            elif repeats >= 3:
                discourage.append(last_action)

    return {"fields": {"facts": facts}, "discourage": discourage}


def alf_after_step(event, state):
    st = {
        "holding": [],
        "empty_seen": [],
        "visited": [],
        "last_action": "",
        "last_nothing": False,
        "repeat_count": 0,
    }
    if state:
        for k in st:
            if k in state:
                st[k] = state[k]

    action = event.get("action") or ""
    obs = (event.get("observation") or "").strip()

    m = _PICK_RE.search(obs)
    if m and m.group(1) not in st["holding"]:
        st["holding"].append(m.group(1))

    m = _PUT_RE.search(obs)
    if m and m.group(1) in st["holding"]:
        st["holding"].remove(m.group(1))

    m = _ARRIVE_RE.search(obs)
    if m:
        loc = m.group(1)
        if loc not in st["visited"]:
            st["visited"].append(loc)
        low = obs.lower()
        if "you see nothing" in low and loc not in st["empty_seen"]:
            st["empty_seen"].append(loc)

    st["last_nothing"] = obs.lower().startswith("nothing happens")
    if action and action == st["last_action"]:
        st["repeat_count"] = st["repeat_count"] + 1
    else:
        st["repeat_count"] = 1
    st["last_action"] = action

    st["holding"] = st["holding"][:4]
    st["empty_seen"] = st["empty_seen"][:8]
    st["visited"] = st["visited"][:16]
    return st
